/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var defaults = require( './../../editor/defaults.js' );
var transform = require( './../transform.js' );


// MAIN //

/**
* Sets a "raw" visualization schema.
*
* @private
* @param {Object} schema - visualization schema
*/
function set( schema ) {
	var def = ( this._state.editor ) ? this._state.editor.defaults : defaults;
	this._raw = schema;
	this._transformed = transform( schema, def );
}


// EXPORTS //

module.exports = set;
